{
  "probability": 0.77,
  "range_low": 0.70,
  "range_high": 0.84,
  "summary": [
    "Forecasts imply the 2/3 majority is unlikely but not impossible; posterior probability ~77%.",
    "Hungary's winner-compensation system amplifies seat shares, which can elevate a bloc's seat count under favorable margins.",
    "Ongoing opposition unity around TISZA and polling momentum reduce odds of a 2/3 majority for Fidesz, but turnout and new entrants introduce uncertainty."
  ],
  "confidence": "medium",
  "narrative": "Starting from the reference-class anchor, updated for structural amplification, opposition consolidation, and turnout/entry dynamics. The calibrated probability of a 2/3 majority is 0.77 with a modest range reflecting remaining uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.25,
      "basis": "Reference-class anchor probability for achieving a two-thirds majority under Hungary's current electoral rules; historical precedence and standard forecaster expectations support this as a baseline before updates."
    },
    "factor_updates": [
      {
        "factor": "Electoral-system amplification (winner-compensation)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Winner-compensation can translate non-majority vote shares into outsized seat shares, materially increasing the chance of 133+ seats when margins tilt in favor of a bloc."
      },
      {
        "factor": "Opposition unity around TISZA",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Polls showing TISZA ahead or contesting Fidesz suggest consolidation that can lift the leading bloc's seat share, nudging toward the threshold without guaranteeing it."
      },
      {
        "factor": "Third-party fragmentation (Our Homeland entering Parliament)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "New entrants can siphon votes and fragment the vote, reducing the probability of a single bloc reaching 133 seats."
      },
      {
        "factor": "Turnout dynamics and mobilization differences",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Higher turnout favorable to the opposition could shift seat allocations toward the 2/3 threshold, though the effect is not guaranteed."
      },
      {
        "factor": "Polling uncertainty and cross-firm disagreements",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Divergent polls add calibration noise; they inform uncertainty rather than decisively steer toward or away from a 2/3 outcome."
      }
    ],
    "synthesis_rationale": "The strong amplification effect from the electoral system provides upward pressure toward a 2/3 outcome, while opposition unity and turnout provide further uplift. Fragmentation risk and poll divergence counterbalance those gains, yielding a posterior around 0.77 with a calibrated range that acknowledges remaining uncertainty and factor correlation."
  }
}

{
  "probability": 0.77,
  "range_low": 0.66,
  "range_high": 0.88,
  "summary": [
    "Posterior probability (0.77) that any party or coalition wins a 2/3 majority (133+ seats) in the 2026 Hungarian elections under current rules.",
    "Strong upward pressure from electoral-system amplification (winner-compensation) and moderate upward pressure from opposition unity around TISZA; fragmentation and turnout volatility offset some of that upside.",
    "Polling projections place leading blocs around 100–110 seats, well below 133, making a 2/3 majority unlikely but not impossible.",
    "Overall uncertainty remains due to cross-firm polling divergence and potential turnout shifts; the range reflects remaining calibration error."
  ],
  "confidence": "medium",
  "narrative": "A Bayesian update using the forecasts and structural rules yields a 0.77 posterior for a 2/3 majority in 2026 Hungary. The winner-compensation mechanism is the dominant upward force, with opposition unity providing additional lift, but fragmentation and turnout volatility cap the upside; most credible polls project seat shares short of 133, keeping the outcome uncertain but plausibly feasible.",
  "justification": {
    "anchor": {
      "probability": 0.25,
      "basis": "reference_class: Two-thirds majority (133+ seats) under Hungary's winner-compensation electoral system; anchor probability drawn from the provided forecast ensemble indicating a relatively low baseline for a 2/3 majority."
    },
    "factor_updates": [
      {
        "factor": "Electoral-system amplification (winner-compensation)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "The mechanism can translate smaller vote shares into outsized seat shares, materially increasing the probability of reaching 133+ seats."
      },
      {
        "factor": "Opposition unity around TISZA",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Consolidation of anti-Fidesz votes increases top-line support and can push seat shares higher, though not deterministically toward 133."
      },
      {
        "factor": "Third-party fragmentation (Our Homeland entering Parliament)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Additional entrants siphon votes and dilute bloc strength, reducing the odds of a clean 2/3 outcome."
      },
      {
        "factor": "Turnout dynamics and mobilization",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Greater turnout favorable to the anti-Fidesz bloc could raise seat shares toward the 2/3 threshold, though effects are uncertain."
      },
      {
        "factor": "Polling uncertainty and cross-firm disagreements",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Divergent poll results and differing seat projections inject uncertainty without a clear directional trend."
      }
    ],
    "synthesis_rationale": "Starting from a cautious anchor, the strongest positive updates come from the structural amplification and perceived opposition consolidation, while fragmentation and turnout volatility temper the gain. Correlations among factors are acknowledged to avoid double counting; the calibrated posterior of 0.77 reflects a plausible, not decisive, probability with a broad uncertainty range."
  }
}

